const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  try {
    // 1. Geometry & Time Definitions
    const arc = ee.Geometry.Point([2.2950, 48.8738]);
    const versailles = ee.Geometry.Point([2.1204, 48.8049]);
    const roiArc = arc.buffer(800).bounds();
    const roiVers = versailles.buffer(2000).bounds();
    const unionGeom = roiArc.union(roiVers, 1);
    const startExact = '2024-08-06';
    const endExact = '2024-08-07';
    const startWide = '2024-08-05';
    const endWide = '2024-08-08';
    const THRESH = 5.0;

    async function evalMODIS(collectionId, startDate, endDate, label) {
      const col = ee.ImageCollection(collectionId)
        .filterDate(startDate, endDate)
        .filterBounds(unionGeom);
      const n = await getInfoAsync(col.size());
      console.log(`${label} ${startDate} Images: ${n}`);
      if (!n || n === 0) return null;
      const img = ee.Image(col.first());
      const imgDate = await getInfoAsync(ee.Date(img.get('system:time_start')).format('YYYY-MM-dd'));
      const qc = img.select('QC_Day');
      const lst = img.select('LST_Day_1km');
      const goodMask = qc.bitwiseAnd(3).lte(1); // bits 0-1 <= 01
      const lstC = lst.updateMask(goodMask).multiply(0.02).subtract(273.15).rename('LST_C');

      async function statsFor(roi, name) {
        const validCount = await getInfoAsync(
          lstC.reduceRegion({ reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9 }).get('LST_C')
        );
        const totalCount = await getInfoAsync(
          qc.reduceRegion({ reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9 }).get('QC_Day')
        );
        const meanC = await getInfoAsync(
          lstC.reduceRegion({ reducer: ee.Reducer.mean(), geometry: roi, scale: 1000, maxPixels: 1e9 }).get('LST_C')
        );
        const cloudPct = (totalCount && validCount != null) ? (100 * (1 - (validCount / totalCount))) : null;
        return { name, meanC, validCount: validCount || 0, totalCount: totalCount || 0, cloudPct };
      }

      const arcStats = await statsFor(roiArc, 'Arc');
      const verStats = await statsFor(roiVers, 'Versailles');
      return { dataset: collectionId, imgDate, arcStats, verStats };
    }

    // 2. Data Acquisition & Check (with fallback)
    let result = await evalMODIS('MODIS/061/MOD11A1', startExact, endExact, 'MOD11A1');
    if (!result) {
      result = await evalMODIS('MODIS/061/MYD11A1', startExact, endExact, 'MYD11A1');
    }
    if (!result) {
      result = await evalMODIS('MODIS/061/MOD11A1', startWide, endWide, 'MOD11A1 wide');
    }
    if (!result) {
      result = await evalMODIS('MODIS/061/MYD11A1', startWide, endWide, 'MYD11A1 wide');
    }
    if (!result) {
      console.log('No data found in available collections for the date/location.');
      console.log('C1: Empty Collection (No images found)');
      console.log('C1');
      return;
    }

    // 3. Processing checks (valid pixels)
    const A = result.arcStats;
    const V = result.verStats;

    // Print concise evidence
    console.log(`Dataset: ${result.dataset}, Image Date: ${result.imgDate}`);
    const arcCloud = (A.cloudPct == null || isNaN(A.cloudPct)) ? 'NA' : A.cloudPct.toFixed(1);
    const verCloud = (V.cloudPct == null || isNaN(V.cloudPct)) ? 'NA' : V.cloudPct.toFixed(1);
    console.log(`Arc LST(C): ${A.meanC != null ? A.meanC.toFixed(2) : 'null'}, Pixels: ${A.validCount}/${A.totalCount}, Cloud%: ${arcCloud}`);
    console.log(`Vers LST(C): ${V.meanC != null ? V.meanC.toFixed(2) : 'null'}, Pixels: ${V.validCount}/${V.totalCount}, Cloud%: ${verCloud}`);

    if (A.totalCount === 0 || V.totalCount === 0 || A.validCount === 0 || V.validCount === 0) {
      console.log('No valid pixels after masking for one or both ROIs.');
      console.log('C2');
      return;
    }

    // 4. Calculation
    const meanArc = A.meanC;
    const meanVer = V.meanC;
    const invalid = (v) => (v === null || isNaN(v) || !isFinite(v) || v < -50 || v > 80);
    if (invalid(meanArc) || invalid(meanVer)) {
      console.log('Invalid LST values encountered.');
      console.log('C3');
      return;
    }
    const delta = meanArc - meanVer;
    console.log(`Delta (Arc - Versailles) = ${delta.toFixed(2)} °C`);

    // 5. Final Answer
    if (delta >= THRESH) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
